export type Customer = {
  yearsWithMHPCO: number;
  previousContracts: number;
};

export type Item = {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
};

const PROCESSING_FEE = 5;

// The MHPCO rounds every gold amount in its own favour. That single rule points
// in opposite arithmetic directions depending on who is paying: money coming in
// rounds up, money going out rounds down. Naming both halves keeps the shared
// policy visible instead of leaving two bare Math calls that look unrelated.
const roundPremiumInMHPCOsFavour = (amount: number): number =>
  Math.ceil(amount);

const roundPayoutInMHPCOsFavour = (amount: number): number =>
  Math.floor(amount);

// The MHPCO price list. The spec gives each item type an insurance value and
// a base premium together, so they live in one table: the set of known item
// types is a single fact, and the two columns cannot drift apart.
type PriceListEntry = {
  insuranceValue: number;
  basePremium: number;
};

const PRICE_LIST: Record<string, PriceListEntry> = {
  sword: { insuranceValue: 1000, basePremium: 100 },
  amulet: { insuranceValue: 600, basePremium: 60 },
  staff: { insuranceValue: 800, basePremium: 80 },
  potion: { insuranceValue: 400, basePremium: 40 },
  rune: { insuranceValue: 250, basePremium: 25 },
  moonstone: { insuranceValue: 250, basePremium: 25 },
};

const CURSED_SURCHARGE_RATE = 0.5;
const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
const HIGH_ENCHANTMENT_THRESHOLD = 5;

const isKnownItemType = (item: Item): boolean => item.type in PRICE_LIST;

const rejectUnknownItemTypes = (items: Item[]): void => {
  const unknown = items.find((item) => !isKnownItemType(item));
  if (unknown) {
    throw new Error(`Unknown item type: ${unknown.type}`);
  }
};

const basePremiumOf = (item: Item): number =>
  PRICE_LIST[item.type].basePremium;

const insuranceValueOf = (item: Item): number =>
  PRICE_LIST[item.type].insuranceValue;

const surchargeRateOf = (item: Item): number =>
  (item.cursed ? CURSED_SURCHARGE_RATE : 0) +
  ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD
    ? HIGH_ENCHANTMENT_SURCHARGE_RATE
    : 0);

const surchargeOf = (item: Item): number =>
  basePremiumOf(item) * surchargeRateOf(item);

const sumBasePremiums = (items: Item[]): number =>
  items.reduce((sum, item) => sum + basePremiumOf(item), 0);

const sumItemSurcharges = (items: Item[]): number =>
  items.reduce((sum, item) => sum + surchargeOf(item), 0);

// Policy-level modifiers are whole percentages of the policy base premium.
// Applying them as `amount * percent / 100` keeps the arithmetic exact:
// `100 * 110 / 100` is 110, whereas `100 * 1.1` is 110.00000000000001.
const applyPercentage = (amount: number, percent: number): number =>
  (amount * percent) / 100;

const FIRST_INSURANCE_SURCHARGE_PERCENTAGE = 10;
const LOYALTY_DISCOUNT_PERCENTAGE = 20;
const LOYALTY_YEARS_THRESHOLD = 2;

const loyaltyDiscountPercentageOf = (customer: Customer): number =>
  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD
    ? LOYALTY_DISCOUNT_PERCENTAGE
    : 0;

const FOLLOW_UP_DISCOUNT_PERCENTAGE = 15;
const FOLLOW_UP_CONTRACTS_THRESHOLD = 1;

const followUpDiscountPercentageOf = (customer: Customer): number =>
  customer.previousContracts >= FOLLOW_UP_CONTRACTS_THRESHOLD
    ? FOLLOW_UP_DISCOUNT_PERCENTAGE
    : 0;

const policyPercentageDeltaOf = (customer: Customer): number =>
  FIRST_INSURANCE_SURCHARGE_PERCENTAGE -
  loyaltyDiscountPercentageOf(customer) -
  followUpDiscountPercentageOf(customer);

const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

const isComponentBlock = (sameTypeGroup: Item[]): boolean =>
  sameTypeGroup.length === BLOCK_SIZE;

const groupByType = (items: Item[]): Item[][] => {
  const groups = new Map<string, Item[]>();
  for (const item of items) {
    const group = groups.get(item.type) ?? [];
    group.push(item);
    groups.set(item.type, group);
  }
  return [...groups.values()];
};

const basePremiumOfGroup = (sameTypeGroup: Item[]): number =>
  isComponentBlock(sameTypeGroup)
    ? BLOCK_BASE_PREMIUM
    : sumBasePremiums(sameTypeGroup);

const policyBasePremiumOf = (items: Item[]): number =>
  groupByType(items).reduce((sum, group) => sum + basePremiumOfGroup(group), 0);

export const quote = (customer: Customer, items: Item[]): number => {
  rejectUnknownItemTypes(items);

  const policyBasePremium = policyBasePremiumOf(items);
  const policyPercentageAdjustment = applyPercentage(
    policyBasePremium,
    policyPercentageDeltaOf(customer),
  );

  return roundPremiumInMHPCOsFavour(
    policyBasePremium +
      sumItemSurcharges(items) +
      policyPercentageAdjustment +
      PROCESSING_FEE,
  );
};

export type Damage = {
  itemType: string;
  amount: number;
};

export type Incident = {
  cause: string;
  damages: Damage[];
};

export type ClaimResult = {
  payout: number;
  remainingCap: number;
};

export const insuranceSum = (items: Item[]): number =>
  items.reduce((sum, item) => sum + insuranceValueOf(item), 0);

const DEDUCTIBLE = 100;

const HIGH_ENCHANTMENT_CLAIM_THRESHOLD = 8;
const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;

const reimbursementRateOf = (item: Item): number =>
  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_THRESHOLD
    ? HIGH_ENCHANTMENT_REIMBURSEMENT_RATE
    : 1;

// Each damage entry carries its own deductible, so reimbursement is decided
// per entry and only then summed into the policy-level total.
const reimbursementFor = (damage: Damage, item: Item): number =>
  damage.amount * reimbursementRateOf(item) - DEDUCTIBLE;

// A damage entry names its item by type, so the insured item it refers to has
// to be looked up in the policy. The cast is a known gap: a damage entry for a
// type the policy does not insure has no item, and the still-todo "not covered
// by the policy" test will drive the validation that closes it.
const insuredItemFor = (damage: Damage, items: Item[]): Item =>
  items.find((item) => item.type === damage.itemType) as Item;

const sumReimbursements = (damages: Damage[], items: Item[]): number =>
  damages.reduce(
    (sum, damage) => sum + reimbursementFor(damage, insuredItemFor(damage, items)),
    0,
  );

export const claim = (
  items: Item[],
  incident: Incident,
  remainingCap: number,
): ClaimResult => {
  const reimbursementBeforeCap = sumReimbursements(incident.damages, items);
  const payout = roundPayoutInMHPCOsFavour(
    Math.min(reimbursementBeforeCap, remainingCap),
  );
  return { payout, remainingCap: remainingCap - payout };
};

import { describe, it, expect } from "vitest";
import { quote, claim, insuranceSum } from "./claim-office.js";

describe("Claim Office - quote: base premiums", () => {
  it("should charge only the 5G processing fee for an empty item list", () => {
    expect(quote({ yearsWithMHPCO: 0, previousContracts: 0 }, [])).toBe(5);
  });
  it("should charge 100G base premium plus fee for a single sword", () => {
    expect(
      quote({ yearsWithMHPCO: 0, previousContracts: 0 }, [{ type: "sword" }]),
    ).toBe(115);
  });
  it("should charge 60G base premium plus fee for a single amulet", () => {
    expect(
      quote({ yearsWithMHPCO: 0, previousContracts: 0 }, [{ type: "amulet" }]),
    ).toBe(71);
  });
  it("should charge 80G base premium plus fee for a single staff", () => {
    expect(
      quote({ yearsWithMHPCO: 0, previousContracts: 0 }, [{ type: "staff" }]),
    ).toBe(93);
  });
  it("should charge 40G base premium plus fee for a single potion", () => {
    expect(
      quote({ yearsWithMHPCO: 0, previousContracts: 0 }, [{ type: "potion" }]),
    ).toBe(49);
  });
  it("should charge 25G base premium plus fee for a single rune", () => {
    expect(
      quote({ yearsWithMHPCO: 0, previousContracts: 0 }, [{ type: "rune" }]),
    ).toBe(33);
  });
  it("should charge 25G base premium plus fee for a single moonstone", () => {
    expect(
      quote({ yearsWithMHPCO: 0, previousContracts: 0 }, [
        { type: "moonstone" },
      ]),
    ).toBe(33);
  });
  it("should sum the base premiums of several different main items", () => {
    expect(
      quote({ yearsWithMHPCO: 0, previousContracts: 0 }, [
        { type: "sword" },
        { type: "amulet" },
      ]),
    ).toBe(181);
  });
});

describe("Claim Office - quote: component blocks", () => {
  it("should charge 50G base premium for 2 runes (no block)", () => {
    expect(
      quote({ yearsWithMHPCO: 0, previousContracts: 0 }, [
        { type: "rune" },
        { type: "rune" },
      ]),
    ).toBe(60);
  });
  it("should charge 60G base premium for exactly 3 runes (block applies)", () => {
    expect(
      quote({ yearsWithMHPCO: 0, previousContracts: 0 }, [
        { type: "rune" },
        { type: "rune" },
        { type: "rune" },
      ]),
    ).toBe(71);
  });
  it("should charge 100G base premium for 4 runes (no block for the remainder)", () => {
    expect(
      quote({ yearsWithMHPCO: 0, previousContracts: 0 }, [
        { type: "rune" },
        { type: "rune" },
        { type: "rune" },
        { type: "rune" },
      ]),
    ).toBe(115);
  });
  it("should charge 175G base premium for 7 runes (no block — a block requires exactly 3)", () => {
    expect(
      quote(
        { yearsWithMHPCO: 0, previousContracts: 0 },
        Array.from({ length: 7 }, () => ({ type: "rune" })),
      ),
    ).toBe(198);
  });
  it("should charge 75G base premium for 2 runes and 1 moonstone (different types do not form a block)", () => {
    expect(
      quote({ yearsWithMHPCO: 0, previousContracts: 0 }, [
        { type: "rune" },
        { type: "rune" },
        { type: "moonstone" },
      ]),
    ).toBe(88);
  });
  it("should charge 120G base premium for 3 runes and 3 moonstones (two separate blocks)", () => {
    expect(
      quote({ yearsWithMHPCO: 0, previousContracts: 0 }, [
        { type: "rune" },
        { type: "rune" },
        { type: "rune" },
        { type: "moonstone" },
        { type: "moonstone" },
        { type: "moonstone" },
      ]),
    ).toBe(137);
  });
});

describe("Claim Office - quote: item-level modifiers", () => {
  it("should add a 50% surcharge on a cursed item's base premium", () => {
    expect(
      quote({ yearsWithMHPCO: 0, previousContracts: 0 }, [
        { type: "sword", enchantment: 3, cursed: true },
      ]),
    ).toBe(165);
  });
  it("should add a 30% surcharge for an item with enchantment exactly 5", () => {
    expect(
      quote({ yearsWithMHPCO: 0, previousContracts: 0 }, [
        { type: "sword", enchantment: 5 },
      ]),
    ).toBe(145);
  });
  it("should not add the high-enchantment surcharge for an item with enchantment 4", () => {
    expect(
      quote({ yearsWithMHPCO: 0, previousContracts: 0 }, [
        { type: "sword", enchantment: 4 },
      ]),
    ).toBe(115);
  });
  it("should add both surcharges for an item that is cursed and enchantment >= 5", () => {
    expect(
      quote({ yearsWithMHPCO: 0, previousContracts: 0 }, [
        { type: "sword", enchantment: 7, cursed: true },
      ]),
    ).toBe(195);
  });
  it("should apply the cursed surcharge only to the cursed item's base premium, not the policy total", () => {
    expect(
      quote({ yearsWithMHPCO: 0, previousContracts: 0 }, [
        { type: "sword", cursed: true },
        { type: "amulet" },
      ]),
    ).toBe(231);
  });
});

describe("Claim Office - quote: policy-level modifiers", () => {
  it("should apply a 10% first insurance surcharge on the policy base premium", () => {
    expect(
      quote({ yearsWithMHPCO: 0, previousContracts: 0 }, [{ type: "sword" }]),
    ).toBe(115);
  });
  it("should apply a 20% loyalty discount for a customer with exactly 2 years with MHPCO", () => {
    expect(
      quote({ yearsWithMHPCO: 2, previousContracts: 0 }, [{ type: "sword" }]),
    ).toBe(95);
  });
  it("should not apply the loyalty discount for a customer with fewer than 2 years", () => {
    expect(
      quote({ yearsWithMHPCO: 1, previousContracts: 0 }, [{ type: "sword" }]),
    ).toBe(115);
  });
  it("should apply a 15% follow-up discount on the customer's second and later contracts", () => {
    expect(
      quote({ yearsWithMHPCO: 0, previousContracts: 1 }, [{ type: "sword" }]),
    ).toBe(100);
  });
  it("should not apply the follow-up discount on the customer's first contract", () => {
    expect(
      quote({ yearsWithMHPCO: 0, previousContracts: 0 }, [{ type: "sword" }]),
    ).toBe(115);
  });
  it("should add the 5G processing fee at the very end, after all other modifiers", () => {
    expect(
      quote({ yearsWithMHPCO: 2, previousContracts: 1 }, [{ type: "sword" }]),
    ).toBe(80);
  });
});

describe("Claim Office - quote: rounding", () => {
  it("should round the final premium up to a whole G", () => {
    expect(
      quote(
        { yearsWithMHPCO: 0, previousContracts: 0 },
        Array.from({ length: 7 }, () => ({ type: "rune" })),
      ),
    ).toBe(198);
  });
});

describe("Claim Office - quote: integration", () => {
  it("should charge 165G for a newcomer's cursed steel sword with enchantment 3", () => {
    expect(
      quote({ yearsWithMHPCO: 0, previousContracts: 0 }, [
        { type: "sword", material: "steel", enchantment: 3, cursed: true },
      ]),
    ).toBe(165);
  });
  it("should charge 160G for a 3-year customer's second contract with a cursed sword of enchantment 7", () => {
    expect(
      quote({ yearsWithMHPCO: 3, previousContracts: 1 }, [
        { type: "sword", material: "steel", enchantment: 7, cursed: true },
      ]),
    ).toBe(160);
  });
});

describe("Claim Office - quote: errors", () => {
  it("should reject a quote containing an item with an unknown type", () => {
    expect(() =>
      quote({ yearsWithMHPCO: 0, previousContracts: 0 }, [
        { type: "broomstick" },
      ]),
    ).toThrow();
  });
});

describe("Claim Office - claim: insurance sum and cap", () => {
  it("should cap the policy payout at twice the insurance sum of a single sword", () => {
    expect(
      claim(
        [{ type: "sword" }],
        { cause: "dragon attack", damages: [{ itemType: "sword", amount: 5000 }] },
        2000,
      ),
    ).toEqual({ payout: 2000, remainingCap: 0 });
  });
  it("should sum the insurance values of several items to derive the cap", () => {
    expect(insuranceSum([{ type: "sword" }, { type: "amulet" }])).toBe(1600);
  });
  it("should base the cap on unmodified insurance values, ignoring premium modifiers", () => {
    expect(insuranceSum([{ type: "sword", cursed: true, enchantment: 7 }])).toBe(
      1000,
    );
  });
  it("should base the cap on the full component insurance values, ignoring the block discount", () => {
    expect(
      insuranceSum([
        { type: "sword" },
        { type: "rune" },
        { type: "rune" },
        { type: "rune" },
      ]),
    ).toBe(1750);
  });
});

describe("Claim Office - claim: standard reimbursement", () => {
  it("should pay the damage amount minus the 100G deductible for a regular sword", () => {
    expect(
      claim(
        [{ type: "sword", material: "steel", enchantment: 3 }],
        { cause: "fire", damages: [{ itemType: "sword", amount: 500 }] },
        2000,
      ),
    ).toEqual({ payout: 400, remainingCap: 1600 });
  });
  it("should pay the damage amount minus the 100G deductible for a damaged rune", () => {
    expect(
      claim(
        [{ type: "rune" }],
        { cause: "fire", damages: [{ itemType: "rune", amount: 200 }] },
        500,
      ),
    ).toEqual({ payout: 100, remainingCap: 400 });
  });
  it("should apply the 100G deductible once per damage entry when several items are damaged", () => {
    expect(
      claim(
        [{ type: "sword" }, { type: "amulet" }],
        {
          cause: "dragon attack",
          damages: [
            { itemType: "sword", amount: 500 },
            { itemType: "amulet", amount: 300 },
          ],
        },
        3200,
      ),
    ).toEqual({ payout: 600, remainingCap: 2600 });
  });
});

describe("Claim Office - claim: special clauses", () => {
  it("should reimburse 50% of the damage before the deductible for enchantment exactly 8", () => {
    expect(
      claim(
        [{ type: "sword", material: "steel", enchantment: 8 }],
        { cause: "fire", damages: [{ itemType: "sword", amount: 1000 }] },
        2000,
      ),
    ).toEqual({ payout: 400, remainingCap: 1600 });
  });
  it("should reimburse dragon material fully before the deductible", () => {
    expect(
      claim(
        [{ type: "sword", material: "dragon", enchantment: 5 }],
        { cause: "fire", damages: [{ itemType: "sword", amount: 800 }] },
        2000,
      ),
    ).toEqual({ payout: 700, remainingCap: 1300 });
  });
  it("should let the 50% enchantment rule win when both the enchantment and dragon clauses apply", () => {
    expect(
      claim(
        [{ type: "sword", material: "dragon", enchantment: 9 }],
        { cause: "fire", damages: [{ itemType: "sword", amount: 1000 }] },
        2000,
      ),
    ).toEqual({ payout: 400, remainingCap: 1600 });
  });
});

describe("Claim Office - claim: cap depletion", () => {
  it("should report the remaining cap after a claim", () => {
    expect(
      claim(
        [{ type: "sword" }],
        { cause: "fire", damages: [{ itemType: "sword", amount: 1500 }] },
        2000,
      ),
    ).toEqual({ payout: 1400, remainingCap: 600 });
  });
  it("should reduce a payout to the remaining cap when the cap is exhausted by successive claims", () => {
    expect(
      claim(
        [{ type: "sword" }],
        { cause: "fire", damages: [{ itemType: "sword", amount: 1500 }] },
        600,
      ),
    ).toEqual({ payout: 600, remainingCap: 0 });
  });
});

describe("Claim Office - claim: rounding", () => {
  it("should round the final payout down to a whole G", () => {
    expect(
      claim(
        [{ type: "sword", material: "steel", enchantment: 8 }],
        { cause: "fire", damages: [{ itemType: "sword", amount: 901 }] },
        2000,
      ),
    ).toEqual({ payout: 350, remainingCap: 1650 });
  });
});

describe("Claim Office - claim: multiple items of the same type", () => {
  it("should treat two damage entries of the same item type as separate damages with their own deductibles", () => {
    expect(
      claim(
        [{ type: "sword" }, { type: "sword" }],
        {
          cause: "dragon attack",
          damages: [
            { itemType: "sword", amount: 500 },
            { itemType: "sword", amount: 300 },
          ],
        },
        4000,
      ),
    ).toEqual({ payout: 600, remainingCap: 3400 });
  });
});

describe("Claim Office - claim: errors", () => {
  it.todo("should reject a claim with a damage entry for an item type not covered by the policy");
  it.todo("should reject a claim with more damage entries of a type than the policy insures");
  it.todo("should reject a claim with a negative damage amount");
});

describe("Claim Office - CLI", () => {
  it.todo("should read a scenario from stdin and write a results array to stdout");
  it.todo("should return one result per step in the same order as the input steps");
  it.todo("should return a premium for a quote step and a payout with remainingCap for a claim step");
  it.todo("should resolve a claim step's policy field to the quote step at that zero-based index");
  it.todo("should exit with a non-zero status and write to stderr for an unknown item type in a quote");
  it.todo("should exit with a non-zero status and write to stderr for a damage entry not covered by the policy");
  it.todo("should exit with a non-zero status and write to stderr for a negative damage amount");
  it.todo("should write no results to stdout when the scenario is rejected");
});

